OutletWorkflowService::StepState OutletWorkflowService::stepStateFromOperationByComposedStepId(const ID &composedStepId, const ID &outletId, const ID &positionId, const QDate &date) const
{
    StepIdentifier stepId = outletWorkflowServiceDL()->stepIdentifierFromWorkflowStepId(composedStepId);

    if (stepId.isValid()) {
        for (const OperationsSourcePtr &source : outletOperationsSourceRegister()->sourceList()) {
            if (source->sourceType() != stepId.type()) {
                continue;
            }

            if (!source->objectIdAllowed(stepId.objectId())) {
                continue;
            }

            AgentOperation::StateCode state = source->state(stepId.objectId(), outletId, positionId, date);

            return { stepId, state };
        }
    }

    for (const OperationsSourcePtr &source : outletOperationsSourceRegister()->sourceList()) {

        StepIdentifier potentialStepId = StepIdentifier::fromCompositeId(composedStepId, source->sourceType());

        if (!potentialStepId.isValid()) {
            continue;
        }

        if (!source->objectIdAllowed(potentialStepId.objectId())) {
            continue;
        }

        AgentOperation::StateCode state = source->state(potentialStepId.objectId(), outletId, positionId, date);

        return { potentialStepId, state };
    }

    return StepState();
}

