       if(arr[i]>0)  positive++;
       if(arr[i]<0)  negative++;
       if(arr[i]===0)  nullish++;
   }
   const positiveRatios=(positive/arr.length).toFixed(6)
  const negativeRatios=(negative/arr.length).toFixed(6)
const nullishRatios=(nullish/arr.length).toFixed(6)
return {positiveRatios,negativeRatios,nullishRatios}
}
